(* [comment removed for export] *)
Definition read_size_val (F : fbv) : Z := Z.min (Z.max 512 (fb_cap F - fb_size F)) 65536.

Lemma read_size_val_range : forall F, 512 <= read_size_val F <= 65536.
Proof. intros F. unfold read_size_val. lia. Qed.

(* [comment removed for export] *)
Definition fb_consume (F : fbv) (k : Z) : fbv :=
  if k <? fb_size F then mkFB (fb_begin F) (fb_in F + k) (fb_out F) (fb_last F) (fb_end F)
  else mkFB (fb_begin F) (fb_begin F) (fb_begin F) (fb_last F) (fb_end F).

(* [comment removed for export] *)
Definition fb_prep_inplace (F : fbv) (n : Z) : bool := n <=? fb_end F - fb_out F.
Definition fb_prep_slide (F : fbv) (n : Z) : bool := n <=? fb_cap F - fb_size F.
Definition fb_newsize (F : fbv) (n : Z) : Z := Z.max (2 * fb_size F) (fb_size F + n).

Section HCW.
  Context {HCEIL : HeapCeil}.

Lemma FlatBuf_cells : forall LB m a F ds, FlatBuf LB m a F ds -> rw_cells rsegs m a (FlatBufCells F).
Proof. intros LB m a F ds (H & _). exact H. Qed.

Lemma FlatBuf_size : forall LB m a F ds, FlatBuf LB m a F ds -> zlength ds = fb_size F.
Proof. intros LB m a F ds (_ & _ & H & _). exact H. Qed.

(* [comment removed for export] *)
Lemma FlatBuf_shape : forall LB m a F ds, FlatBuf LB m a F ds ->
  0 <= fb_begin F /\ fb_begin F <= fb_in F <= fb_out F /\ fb_out F <= fb_last F <= fb_end F /\ fb_end F <= hceil
  /\ (F = FB_empty \/ (0 < fb_begin F /\ fb_begin F mod 16 = 0 /\ 0 < fb_cap F
                       /\ (fb_end F <= 0x10000 \/ 0xb4000 <= fb_begin F)
                       /\ exists p, In (p, fb_begin F, fb_cap F) LB)).
Proof.
  intros LB m a F ds (_ & OK & _ & _). pose proof hceil_pos as HP.
  destruct OK as [-> | (p & IN & (R1 & R2 & R3 & R4 & R5) & CP & S1 & S2)]; unfold fb_cap in *; cbn in *.
  - repeat split; cbn; try lia. left; reflexivity.
  - repeat split; try lia. right. repeat split; try lia. exists p. exact IN.
Qed.

(* [comment removed for export] *)
Lemma fb_block_transport : forall W m m' (FB : fbv) (ds : list byte),
  (FB <> FB_empty -> exists pre junk,
      rw_cells rsegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]) ->
  munch W m m' -> wmono rsegs m m' ->
  fb_begin FB <= fb_in FB -> zlength ds = fb_out FB - fb_in FB -> fb_out FB <= fb_end FB ->
  disjoint_from W (fb_begin FB) (fb_end FB - fb_begin FB) ->
  (FB <> FB_empty -> exists pre junk,
      rw_cells rsegs m' (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]).
Proof.
  intros W m m' FB ds BLK MU WM H1 H2 H3 D NE. destruct (BLK NE) as (pre & junk & B). exists pre, junk.
  eapply rw_cells_transport; [exact B | exact MU | exact WM |].
  cbn [cells_size csize Nat.add]. unfold zlength in H2.
  replace (Z.of_nat (Z.to_nat (fb_in FB - fb_begin FB) + (length ds + (Z.to_nat (fb_end FB - fb_out FB) + 0))))
    with (fb_end FB - fb_begin FB) by lia.
  exact D.
Qed.

Lemma FlatBuf_of_parts : forall LB m a FB ds,
  rw_cells rsegs m a (FlatBufCells FB) -> fb_ok LB FB -> zlength ds = fb_size FB ->
  (FB <> FB_empty -> exists pre junk,
      rw_cells rsegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk]) ->
  FlatBuf LB m a FB ds.
Proof. intros. split; [assumption|]. split; [assumption|]. split; assumption. Qed.

(* [comment removed for export] *)
Lemma fb_block_src : forall m (FB : fbv) (ds pre bj : list byte) (k : nat),
  rw_cells rsegs m (fb_begin FB) [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) bj] ->
  fb_begin FB <= fb_in FB -> (k <= length ds)%nat ->
  bytes_at rsegs m (fb_in FB) (firstn k ds).
Proof.
  intros m FB ds pre bj k [[WF B] _] H1 Hk. cbn in WF. destruct WF as (L1 & _ & L3 & _). cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite L1 in B.
  replace (fb_begin FB + Z.of_nat (Z.to_nat (fb_in FB - fb_begin FB))) with (fb_in FB) in B by lia.
  apply bytes_at_app in B. destruct B as [B _].
  rewrite <- (firstn_skipn k ds) in B. apply bytes_at_app in B. destruct B as [B _]. exact B.
Qed.

(* [comment removed for export] *)
Lemma rw_cells_split_CB : forall m A (n k : nat) (bs : list byte),
  rw_cells rsegs m A [CB n bs] -> (k <= n)%nat ->
  rw_cells rsegs m A [CB k (firstn k bs)] /\ rw_cells rsegs m (A + Z.of_nat k) [CB (n - k)%nat (skipn k bs)].
Proof.
  intros m A n k bs H Hk. pose proof H as [[WF _] _]. cbn in WF. destruct WF as [L _].
  assert (R : rw_cells rsegs m A ([CB k (firstn k bs)] ++ [CB (n - k)%nat (skipn k bs)])).
  { eapply rw_cells_reshape; [exact H | cbn; rewrite length_firstn, length_skipn; repeat split; lia | ].
    cbn [cells_bytes cbytes app]. rewrite !app_nil_r. apply firstn_skipn. }
  apply rw_cells_app in R. cbn [cells_size csize Nat.add] in R. rewrite Nat.add_0_r in R. exact R.
Qed.

Lemma rw_cells_join_CB : forall m A (n k : nat) (bs1 bs2 : list byte),
  rw_cells rsegs m A [CB k bs1] -> rw_cells rsegs m (A + Z.of_nat k) [CB n bs2] ->
  rw_cells rsegs m A [CB k bs1; CB n bs2].
Proof.
  intros m A n k bs1 bs2 H1 H2. change [CB k bs1; CB n bs2] with ([CB k bs1] ++ [CB n bs2]). apply rw_cells_app.
  cbn [cells_size csize Nat.add]. rewrite Nat.add_0_r. split; assumption.
Qed.



