Definition read_size_post (ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (read_size_val FB)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m (seg_rom rsegs)
    /\ munch [] m m /\ wmono rsegs m m /\ mem_inv rsegs m.

Definition read_size_stmt : Prop :=
  forall (fb : Z) (LB : list block) (FB : fbv) (ds : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FlatBuf LB m fb FB ds ->
  fb mod 8 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (read_size_post ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc FB m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz fb) (wz 65536) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_READ_SIZE_FB) fc None m (seg_rom rsegs)).

