(* [comment removed for export] *)
Definition fbp_seg3_post (sp gp tp s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v mx : word) (fb A' len n ns lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v (Z_to_bv 64 (A' + len)) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (fb, fb + 40)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' fb [C8 (Z_to_bv 64 A'); C8 (Z_to_bv 64 A'); C8 (Z_to_bv 64 (A' + len)); C8 (Z_to_bv 64 (A' + len + n));
                           C8 (Z_to_bv 64 (A' + ns)); C8 mx].
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma fbp_seg3 : forall (fb A' len n ns lo : Z) (rav s0v s1v s2v s3v s4v s5v s6v s7v b0 i0 o0 l0 e0 mx : word) (fj : list byte)
    sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s6 s8 s9 s10 s11 t3 t4 t5 t6 ra
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m fb [C8 b0; C8 i0; C8 o0; C8 l0; C8 e0; C8 mx] -> fb mod 8 = 0 ->
  rw_cells rsegs m (bv_unsigned sp + -112) (fbp_frame fj s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
  stk rsegs m lo (bv_unsigned sp + -112) -> lo + 112 <= bv_unsigned sp -> hceil <= lo ->
  (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) ->
  0 < A' -> 0 <= len -> 0 <= n -> len + n <= ns -> A' + ns <= hceil ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (fbp_seg3_post sp gp tp s8 s9 s10 s11 F fc rav s0v s1v s2v s3v s4v s5v s6v s7v mx fb A' len n ns lo m)
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 fb) a0 a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 len) s3 s4 (Z_to_bv 64 ns) s6 (Z_to_bv 64 A') s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 FBP_RET2) fc None m (seg_rom rsegs)).
