Definition fbp_seg2_post (sp gp tp s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (fb n A' ns : Z) (FB : fbv) (ds junkA : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' a1' : word) (pc' : Z) t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 fb) a0' a1' a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 ns) (Z_to_bv 64 (fb_cap FB))
                  (Z_to_bv 64 A') s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 pc') fc None m' (seg_rom rsegs)
    /\ munch [(A', A' + fb_size FB)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' A' [CB (Z.to_nat (fb_size FB)) ds; CB (Z.to_nat (ns - fb_size FB)) (skipn (Z.to_nat (fb_size FB)) junkA)]
    /\ ((FB = FB_empty /\ pc' = FBP_RET2)
        \/ (FB <> FB_empty /\ pc' = ROPDEL2 /\ ra' = Z_to_bv 64 FBP_RET2
            /\ a0' = Z_to_bv 64 (fb_begin FB) /\ a1' = Z_to_bv 64 (fb_cap FB))).
