Lemma fbp_seg2 : forall (fb n A' ns : Z) (LB : list block) (FB : fbv) (ds junkA : list byte)
    ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FlatBuf LB m fb FB ds ->
  0 <= n -> fb_cap FB + n < 2^30 -> fb_size FB + n <= ns -> ns < 2^31 ->
  rw_cells rsegs m A' [CB (Z.to_nat ns) junkA] -> 0 < A' -> A' + ns <= hceil ->
  (A' + ns <= fb_begin FB \/ fb_end FB <= A') ->
  mem_inv rsegs m ->
  evt rsegs (fbp_seg2_post sp gp tp s8 s9 s10 s11 F fc fb n A' ns FB ds junkA m)
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 fb) (Z_to_bv 64 A') a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 ns) (Z_to_bv 64 (fb_cap FB))
              s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 FBP_RET1) fc None m (seg_rom rsegs)).
